<?php get_header(); ?><main id="main-content" class="site-main container section-space"><header class="page-header"><p class="eyebrow"><?php esc_html_e( 'Archive', 'meridian-news' ); ?></p><h1><?php the_archive_title(); ?></h1><?php the_archive_description( '<div class="archive-description">', '</div>' ); ?></header><?php if ( have_posts() ) : ?><div class="card-grid"><?php while ( have_posts() ) : the_post(); get_template_part( 'template-parts/content', 'card' ); endwhile; ?></div><?php meridian_news_pagination(); else : ?><div class="empty-state"><h2><?php esc_html_e( 'No stories found', 'meridian-news' ); ?></h2></div><?php endif; ?></main><?php get_footer(); ?>
